long long powMod(long long base, long long exp, int mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long nCr(int n, int r, vector<long long>& fac, int mod) {
    long long numerator = fac[n];
    long long denominator = (fac[r] * fac[n - r]) % mod;
